import type {IncomingMessage} from '../../types/messages.js';

const MAX_CONTENT_LENGTH = 10000;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  switch (message.type) {
    case 'user_message':
      return validateUserMessage(message);
    case 'ping':
      return validatePingMessage(message);
    case 'list_sessions':
      return validateListSessionsMessage(message);
    default:
      return {valid: false, error: `Unknown message type: ${message.type}`};
  }
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  if (
    message.limit !== undefined &&
    (typeof message.limit !== 'number' || !Number.isInteger(message.limit) || message.limit < 0)
  ) {
    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
  }

  const data: Extract<IncomingMessage, {type: 'list_sessions'}> = {type: 'list_sessions'};
  if (message.limit !== undefined) data.limit = message.limit as number;

  if (message.before !== undefined) {
    if (typeof message.before !== 'object' || message.before === null || Array.isArray(message.before)) {
      return {valid: false, error: 'list_sessions before must be a cursor'};
    }
    const before = message.before as Record<string, unknown>;
    if (typeof before.sessionId !== 'string' || before.sessionId.length < 1 || before.sessionId.length > 128) {
      return {valid: false, error: 'list_sessions before.sessionId must be 1–128 characters'};
    }
    if (
      (typeof before.updatedAt !== 'string' && typeof before.updatedAt !== 'number') ||
      !Number.isFinite(new Date(before.updatedAt).getTime())
    ) {
      return {valid: false, error: 'list_sessions before.updatedAt must be a valid timestamp'};
    }
    data.before = {updatedAt: before.updatedAt, sessionId: before.sessionId};
  }

  return {valid: true, data};
}

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

// Local counterpart of the Lore spec-coverage job that consumes these links: a `([validated by](...))`
// link only counts when it sits in its statement's trailing parenthetical, so a
// link anywhere else is reported here rather than silently dropped there.
// Segmentation and link parsing come from the published spec domain
// of @re-cinq/eslint-plugin-re-lint (AGENTS.md § Spec Test Links).

import { readFileSync, readdirSync } from "node:fs";
import { join, relative, resolve } from "node:path";
import process from "node:process";
import { findMisplacedCoverageLinks } from "@re-cinq/eslint-plugin-re-lint/spec/spec-link-parser.js";
import { segmentStatements } from "@re-cinq/eslint-plugin-re-lint/spec/spec-segment.js";
import { root } from "./lib/repo-root.mjs";

const USAGE =
  "usage: check-spec-links.mjs [--json] [spec-path ...]\n" +
  "spec paths resolve against the repo root, not the working directory; an absolute path is taken as given";

const args = process.argv.slice(2);
const flags = args.filter((arg) => arg.startsWith("--"));
const specArgs = args.filter((arg) => !arg.startsWith("--"));

for (const flag of flags) {
  if (flag === "--json") {
    continue;
  }
  process.stderr.write(`${USAGE}\n`);
  process.exit(2);
}

const asJson = flags.includes("--json");

const discoverSpecs = () => {
  const specsDir = join(root, "specs");
  const slugs = readdirSync(specsDir, { withFileTypes: true })
    .filter((entry) => entry.isDirectory())
    .map((entry) => entry.name)
    .sort();

  return [...slugs.map((slug) => `specs/${slug}/spec.md`), ".specify/spec.md"];
};

const specPaths =
  specArgs.length > 0
    ? specArgs.map((path) => relative(root, resolve(root, path)))
    : discoverSpecs();

const readSpec = (specPath) => {
  try {
    return readFileSync(join(root, specPath), "utf8");
  } catch (error) {
    process.stderr.write(`cannot read spec ${specPath}: ${error.message}\n`);
    process.exit(2);
  }
};

const findings = [];
const specsWithFindings = new Set();
let statementsScanned = 0;

for (const specPath of specPaths) {
  const content = readSpec(specPath);

  for (const statement of segmentStatements(content)) {
    statementsScanned += 1;

    for (const link of findMisplacedCoverageLinks(statement.text)) {
      findings.push({
        spec: specPath,
        line: statement.line ?? null,
        path: link.path,
        anchorLine: link.line,
        label: link.label,
        statement: statement.text,
      });
      specsWithFindings.add(specPath);
    }
  }
}

const reportLines = () => {
  const lines = findings.map((finding) => {
    const anchor = finding.anchorLine === null ? "" : `#L${finding.anchorLine}`;
    const line = finding.line ?? "?";

    return `${finding.spec}:${line}: ${finding.path}${anchor} cited outside the statement's trailing parenthetical`;
  });

  lines.push(
    `misplaced: ${findings.length} across ${specsWithFindings.size} specs (${statementsScanned} statements scanned)`
  );

  return lines;
};

// process.exitCode, not process.exit: exiting truncates a large stdout write
// to a pipe.
process.exitCode = findings.length > 0 ? 1 : 0;
process.stdout.write(
  asJson ? `${JSON.stringify(findings, null, 2)}\n` : `${reportLines().join("\n")}\n`
);

